import{z as s,x as A,o as B,c as d,q as l,j as i,D as e,d as r,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"X 射线与近场","description":"","frontmatter":{"title":"X 射线与近场","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/xray-near-field.md","filePath":"litho/xray-near-field.md","lastUpdated":1791063341000}'),p={name:"litho/xray-near-field.md"};function h(m,a,D,f,F,c){const t=A("Mermaid");return B(),d("div",null,[a[2]||(a[2]=l('<h1 id="x-射线与近场" tabindex="-1">X 射线与近场 <a class="header-anchor" href="#x-射线与近场" aria-label="Permalink to &quot;X 射线与近场&quot;">​</a></h1><div class="epigraph"><p>更短的波长在 1980–90 年代走过接近式 X 射线；掩模、间隙与源让它让位给延长寿命的 193 nm。近场则用倏逝波，焦深薄到几乎不是扫描机。</p><footer>—— 对照 X-ray lithography（IBM 等传统）与近场/倏逝光刻的公开历史</footer></div><p><a href="/litho/interference-lithography">上一课</a>展示无透镜周期。缺口是短波接近式与倏逝。本课钉 X 射线与近场。封装尺度的激光直写，留给<a href="/litho/laser-direct-write-packaging">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接近式 X 射线光刻：掩模贴近晶圆，用同步辐射或等离子源，分辨率好，工业上卡在掩模（吸收体、支架）、间隙控制、源与对准。193 浸没 + RET + 多重在成本上赢了，路线被放弃为逻辑主路径。近场/表面等离子体光刻：突破远场衍射，但工作距离纳米级，不适合晶圆扫描产能与形貌。</p><p><span class="marginnote">「倏逝波」就是贴着结构表面、不向前传播的一层「贴地光」：强度随离开表面的距离指数衰减，几十纳米外几乎归零——所以近场光刻必须把基底贴到表面几十纳米以内，产线根本跑不了这个距离。</span></p><p>缺口是<strong>历史岔路</strong>，不是再推瑞利去证明 X 射线「应该赢」。课程要记住：更短 λ 不是充分条件。</p><p><span class="marginnote">常见误区：「波长更短就一定赢」。X 射线分辨率确实好，但产线要的是掩模、源、对准、颗粒容忍一整套都能量产——193 浸没靠在成熟投影光机上做加法，赢了整套推倒重建。</span></p><h3 id="liga-与-mems" tabindex="-1">LIGA 与 MEMS <a class="header-anchor" href="#liga-与-mems" aria-label="Permalink to &quot;LIGA 与 MEMS&quot;">​</a></h3><p>厚胶 X 射线在 MEMS/LIGA 仍有尼奇，对象是高 AR 金属结构，不是 CMOS 金属节距。后课 MEMS 会点到。</p><p><span class="marginnote">EUV 是反射投影，不是 1990s 接近式 X 射线的复活。不要把两者混成「都是短波所以一样」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读史：为何 157 nm 与 X 射线让位浸没。近场：实验室演示 vs 晶圆 wph 算术（工作距离、平整度）。评估替代技术时沿用同一算术。</p>',13)),(B(),i(n,null,{default:e(()=>[o(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%221980s%EF%BC%9A%E9%80%89%E4%B8%8B%E4%B8%80%E4%BB%A3%E5%85%89%E5%88%BB%E8%B7%AF%E7%BA%BF%22%5D%20--%3E%20X%5B%22%E6%8E%A5%E8%BF%91%E5%BC%8F%20X%20%E5%B0%84%E7%BA%BF%22%5D%0A%20%20Q%20--%3E%20DUV%5B%22193%20nm%20%2B%20%E6%B5%B8%E6%B2%A1%20%2B%20RET%22%5D%0A%20%20X%20--%3E%20B1%5B%22%E5%88%86%E8%BE%A8%E7%8E%87%E5%A5%BD%EF%BC%8C%E4%BD%86%E6%8E%A9%E6%A8%A1%2F%E9%97%B4%E9%9A%99%2F%E6%BA%90%E5%85%A8%E8%A6%81%E9%87%8D%E5%BB%BA%22%5D%0A%20%20DUV%20--%3E%20B2%5B%22%E6%B2%BF%E7%94%A8%E6%8A%95%E5%BD%B1%E5%85%89%E5%AD%A6%E4%B8%8E%E4%BA%A7%E4%B8%9A%E9%93%BE%EF%BC%8C%E6%88%90%E6%9C%AC%E9%80%92%E8%BF%9B%22%5D%0A%20%20B1%20--%3E%20W%5B%22%E9%80%80%E5%87%BA%E9%80%BB%E8%BE%91%E4%B8%BB%E7%BA%BF%EF%BC%8C%E7%95%99%20MEMS%20%E5%B0%BC%E5%A5%87%22%5D%0A%20%20B2%20--%3E%20W2%5B%22%E6%88%90%E4%B8%BA%E9%87%8F%E4%BA%A7%E4%B8%BB%E8%B7%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"接近式衍射与半影随间隙变；间隙要小，颗粒与形貌不可忍——pellicle 逻辑的反面。近场强度随距离指数衰减，台阶直接毁掉均匀性。投影光学把掩模放到远处共轭，正是为了躲这两者。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：几何半影模糊约等于「间隙 × 源尺寸与源距之比」——间隙从 10 µm 放大到 40 µm，边缘模糊跟着变成四倍。这就是接近式曝光把间隙公差压到微米以下的算术来源。")],-1)),(B(),i(n,null,{default:e(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20XR%5B%22%E6%8E%A5%E8%BF%91%E5%BC%8F%20X%20%E5%B0%84%E7%BA%BF%22%5D%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%20%2F%20%E9%97%B4%E9%9A%99%20%2F%20%E6%BA%90%E5%A2%99%22%5D%0A%20%20NF%5B%22%E8%BF%91%E5%9C%BA%E5%80%8F%E9%80%9D%22%5D%20--%3E%20GAP%5B%22%E5%B7%A5%E4%BD%9C%E8%B7%9D%E7%A6%BB%E5%A2%99%22%5D%0A%20%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E5%85%89%E5%AD%A6%22%5D%20--%3E%20FAR%5B%22%E8%BF%9C%E5%9C%BA%E5%85%B1%E8%BD%AD%20%2B%20%E4%BA%A7%E8%83%BD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不宣布近场永远无用（存储、模板可能）。不把同步辐射当已死的科学。本课不重开 EUV 源物理。</p><p>后课默认：短波接近式不是先进 CMOS 主路；下一课波长更长、场更大的封装激光直写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>接近式 X 射线卡在掩模、间隙与源，被 193 路径取代为逻辑主线。</li><li>近场破远场衍射，工作距离与形貌不适合扫描产线。</li><li>EUV 投影 ≠ 接近式 X 射线。</li><li>出处：X-ray lithography 产业史；近场光刻实验室传统。</li></ul>',5))])}const _=s(p,[["render",h]]);export{C as __pageData,_ as default};
